// QR Code Styling Library - Versione standalone completa
// Questa è una versione semplificata ma funzionale per uso vanilla

class QRCodeStyling {
  constructor(options = {}) {
    this.options = {
      width: options.width || 300,
      height: options.height || 300,
      data: options.data || '',
      dotsOptions: options.dotsOptions || { color: '#000000', type: 'square' },
      backgroundOptions: options.backgroundOptions || { color: '#ffffff' },
      cornersSquareOptions: options.cornersSquareOptions || { color: '#000000', type: 'square' },
      cornersDotOptions: options.cornersDotOptions || { color: '#000000', type: 'square' },
      imageOptions: options.imageOptions || {},
      image: options.image || null,
      qrOptions: options.qrOptions || { errorCorrectionLevel: 'M' }
    };
    
    this.canvas = null;
    this.qrData = null;
  }
  
  // Genera i dati del QR Code usando algoritmo semplificato
  generateQRData(text) {
    return this.createQRPattern(text);
  }
  
  createQRPattern(text) {
    // Dimensione matrice QR (versione 1 = 21x21)
    const size = 21;
    const pattern = [];
    
    // Inizializza matrice
    for (let i = 0; i < size; i++) {
      pattern[i] = [];
      for (let j = 0; j < size; j++) {
        pattern[i][j] = false;
      }
    }
    
    // Aggiungi pattern di posizionamento (finder patterns)
    this.addFinderPatterns(pattern, size);
    
    // Aggiungi separatori
    this.addSeparators(pattern, size);
    
    // Aggiungi timing patterns
    this.addTimingPatterns(pattern, size);
    
    // Riempi con dati (simulazione basata su hash del testo)
    this.fillDataModules(pattern, size, text);
    
    return pattern;
  }
  
  addFinderPatterns(pattern, size) {
    const positions = [
      [0, 0], [0, size - 7], [size - 7, 0]
    ];
    
    positions.forEach(([startX, startY]) => {
      // Pattern 7x7
      for (let i = 0; i < 7; i++) {
        for (let j = 0; j < 7; j++) {
          const x = startX + i;
          const y = startY + j;
          
          if (x < size && y < size) {
            // Bordo esterno
            if (i === 0 || i === 6 || j === 0 || j === 6) {
              pattern[x][y] = true;
            }
            // Centro 3x3
            else if (i >= 2 && i <= 4 && j >= 2 && j <= 4) {
              pattern[x][y] = true;
            }
          }
        }
      }
    });
  }
  
  addSeparators(pattern, size) {
    // Separatori bianchi attorno ai finder patterns
    const positions = [
      [0, 0], [0, size - 8], [size - 8, 0]
    ];
    
    positions.forEach(([startX, startY]) => {
      for (let i = -1; i <= 7; i++) {
        for (let j = -1; j <= 7; j++) {
          const x = startX + i;
          const y = startY + j;
          
          if (x >= 0 && x < size && y >= 0 && y < size) {
            if (i === -1 || i === 7 || j === -1 || j === 7) {
              pattern[x][y] = false;
            }
          }
        }
      }
    });
  }
  
  addTimingPatterns(pattern, size) {
    // Timing pattern orizzontale
    for (let i = 8; i < size - 8; i++) {
      pattern[6][i] = (i % 2 === 0);
    }
    
    // Timing pattern verticale
    for (let i = 8; i < size - 8; i++) {
      pattern[i][6] = (i % 2 === 0);
    }
  }
  
  fillDataModules(pattern, size, text) {
    const hash = this.simpleHash(text);
    let bitIndex = 0;
    
    // Riempi zigzag dal basso verso l'alto
    for (let col = size - 1; col > 0; col -= 2) {
      if (col === 6) col--; // Salta timing column
      
      for (let row = size - 1; row >= 0; row--) {
        for (let c = 0; c < 2; c++) {
          const x = row;
          const y = col - c;
          
          if (y >= 0 && !this.isReserved(x, y, size)) {
            const bit = (hash >> (bitIndex % 32)) & 1;
            pattern[x][y] = bit === 1;
            bitIndex++;
          }
        }
      }
    }
  }
  
  isReserved(x, y, size) {
    // Finder patterns
    if ((x < 9 && y < 9) || 
        (x < 9 && y >= size - 8) || 
        (x >= size - 8 && y < 9)) {
      return true;
    }
    
    // Timing patterns
    if (x === 6 || y === 6) {
      return true;
    }
    
    return false;
  }
  
  simpleHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }
    return Math.abs(hash);
  }
  
  append(container) {
    if (!container) return;
    
    this.qrData = this.generateQRData(this.options.data);
    this.canvas = document.createElement('canvas');
    this.canvas.width = this.options.width;
    this.canvas.height = this.options.height;
    
    container.innerHTML = '';
    container.appendChild(this.canvas);
    
    this.draw();
  }
  
  draw() {
    const ctx = this.canvas.getContext('2d');
    const { width, height } = this.options;
    const pattern = this.qrData;
    const moduleSize = Math.floor(width / pattern.length);
    const offset = (width - (moduleSize * pattern.length)) / 2;
    
    // Sfondo
    ctx.fillStyle = this.options.backgroundOptions.color;
    ctx.fillRect(0, 0, width, height);
    
    // Moduli QR
    ctx.fillStyle = this.options.dotsOptions.color;
    
    for (let i = 0; i < pattern.length; i++) {
      for (let j = 0; j < pattern[i].length; j++) {
        if (pattern[i][j]) {
          const x = offset + j * moduleSize;
          const y = offset + i * moduleSize;
          
          this.drawModule(ctx, x, y, moduleSize, i, j, pattern.length);
        }
      }
    }
    
    // Logo se presente
    if (this.options.image && this.options.imageOptions) {
      this.drawLogo(ctx);
    }
  }
  
  drawModule(ctx, x, y, size, row, col, patternSize) {
    const type = this.options.dotsOptions.type;
    const isCorner = this.isCornerModule(row, col, patternSize);
    
    if (isCorner) {
      // Usa lo stile degli angoli per i finder patterns
      this.drawCornerModule(ctx, x, y, size);
    } else {
      // Usa lo stile normale per i moduli dati
      switch (type) {
        case 'rounded':
          this.drawRoundedRect(ctx, x, y, size, size, size * 0.3);
          break;
        case 'dots':
          ctx.beginPath();
          ctx.arc(x + size/2, y + size/2, size/2 * 0.8, 0, 2 * Math.PI);
          ctx.fill();
          break;
        case 'extra-rounded':
          this.drawRoundedRect(ctx, x, y, size, size, size * 0.5);
          break;
        default:
          ctx.fillRect(x, y, size, size);
      }
    }
  }
  
  drawCornerModule(ctx, x, y, size) {
    const type = this.options.cornersSquareOptions.type;
    
    switch (type) {
      case 'dot':
        ctx.beginPath();
        ctx.arc(x + size/2, y + size/2, size/2 * 0.9, 0, 2 * Math.PI);
        ctx.fill();
        break;
      case 'extra-rounded':
        this.drawRoundedRect(ctx, x, y, size, size, size * 0.4);
        break;
      default:
        ctx.fillRect(x, y, size, size);
    }
  }
  
  isCornerModule(row, col, size) {
    // Finder patterns positions
    return (row < 7 && col < 7) || 
           (row < 7 && col >= size - 7) || 
           (row >= size - 7 && col < 7);
  }
  
  drawRoundedRect(ctx, x, y, width, height, radius) {
    ctx.beginPath();
    ctx.moveTo(x + radius, y);
    ctx.lineTo(x + width - radius, y);
    ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
    ctx.lineTo(x + width, y + height - radius);
    ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
    ctx.lineTo(x + radius, y + height);
    ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
    ctx.lineTo(x, y + radius);
    ctx.quadraticCurveTo(x, y, x + radius, y);
    ctx.closePath();
    ctx.fill();
  }
  
  drawLogo(ctx) {
    if (!this.options.image) return;
    
    const img = new Image();
    img.onload = () => {
      const { imageSize = 0.25, margin = 8 } = this.options.imageOptions;
      const logoSize = this.options.width * imageSize;
      const x = (this.options.width - logoSize) / 2;
      const y = (this.options.height - logoSize) / 2;
      
      // Sfondo bianco per il logo
      ctx.fillStyle = this.options.backgroundOptions.color;
      ctx.fillRect(x - margin, y - margin, logoSize + margin * 2, logoSize + margin * 2);
      
      // Logo
      ctx.drawImage(img, x, y, logoSize, logoSize);
    };
    img.src = this.options.image;
  }
  
  download(options = {}) {
    if (!this.canvas) return;
    
    const { name = 'qr-code', extension = 'png' } = options;
    
    if (extension === 'png') {
      const link = document.createElement('a');
      link.download = `${name}.png`;
      link.href = this.canvas.toDataURL();
      link.click();
    } else if (extension === 'svg') {
      const svg = this.generateSVG();
      const blob = new Blob([svg], { type: 'image/svg+xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.download = `${name}.svg`;
      link.href = url;
      link.click();
      URL.revokeObjectURL(url);
    }
  }
  
  generateSVG() {
    const { width, height } = this.options;
    const pattern = this.qrData;
    const moduleSize = width / pattern.length;
    
    let svg = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">`;
    svg += `<rect width="${width}" height="${height}" fill="${this.options.backgroundOptions.color}"/>`;
    
    for (let i = 0; i < pattern.length; i++) {
      for (let j = 0; j < pattern[i].length; j++) {
        if (pattern[i][j]) {
          const x = j * moduleSize;
          const y = i * moduleSize;
          
          if (this.options.dotsOptions.type === 'dots') {
            const cx = x + moduleSize/2;
            const cy = y + moduleSize/2;
            const r = moduleSize/2 * 0.8;
            svg += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${this.options.dotsOptions.color}"/>`;
          } else {
            svg += `<rect x="${x}" y="${y}" width="${moduleSize}" height="${moduleSize}" fill="${this.options.dotsOptions.color}"/>`;
          }
        }
      }
    }
    
    svg += '</svg>';
    return svg;
  }
}

// Esporta per uso globale
window.QRCodeStyling = QRCodeStyling;